use super::*;

/// Whether an event fits one datagram — the bound that stops a crafted frame
/// silencing the report about itself.
pub fn fits_one_datagram(e: &Event) -> bool {
    Frame::Delta(e.clone())
        .encode()
        .map(|b| b.len() <= MAX_PLAINTEXT_BYTES)
        .unwrap_or(false)
}
